   "q": "$z=x\\ln y$, $x=s^2t$, $y=s+t$일 때 $(s,t)=(1,1)$에서 $\\dfrac{\\partial z}{\\partial s}$, $\\dfrac{\\partial z}{\\partial t}$를 구하라.",
