   "hint": "$|\\mathbf a\\times\\mathbf b|=|\\mathbf a||\\mathbf b|\\sin\\theta$, $\\mathbf a\\cdot\\mathbf b=|\\mathbf a||\\mathbf b|\\cos\\theta$. 두 사영은 각각 $\\mathbf a$, $\\mathbf b$의 스칼라배예요.",
