   "hint": "$L_2$를 $x=2+2s,\\ y=1+s,\\ z=-s$로 매개화. 거리 $=\\dfrac{|\\mathbf n\\cdot\\overrightarrow{P_1P_2}|}{|\\mathbf n|}$, $\\mathbf n=\\mathbf v_1\\times\\mathbf v_2$",
