   "q": "(a) 평면 $2x+y+mz=4$가 타원면 $x^2+\\dfrac{y^2}{4}+\\dfrac{z^2}{2}=1$에 접할 때 양수 $m$을 구하라.<br>(b) (a)의 $m$에 대해 이 평면이 포물면 $z=x^2+y^2+k$에도 접할 때 실수 $k$를 구하라.",
   "hint": "(a) 접점 $(a,b,c)$에서 접평면 $ax+\\tfrac b4y+\\tfrac c2z=1$과 주어진 평면의 계수를 비교. (b) 포물면의 법선 $\\langle2p,2q,-1\\rangle$이 $\\langle2,1,m\\rangle$과 평행",
