   "q": "$f(x,y,z)=x^2z+yz^3-xy$이고 미분가능한 함수 $g(x,y)$가 $g(2,1)=1$, $f\\big(x,y,g(x,y)\\big)=3$을 만족한다.<br>(a) $(2,1)$에서 $g$가 가장 빠르게 증가하는 방향의 방향도함수를 구하라.&emsp;(b) 선형근사로 $g(2.1,\\ 0.8)$의 근삿값을 구하라.",
