   "q": "$D_1$, $D_2$가 각각 원판 $x^2+y^2\\le1$, $x^2+y^2\\le2y$일 때 $\\displaystyle\\iint_{D_1\\cup D_2}(x^2+y^2)\\,dA$를 계산하라.",
   "hint": "$D_1\\cup D_2=D_1\\ \\cup\\ (D_2$ 중 $D_1$ 밖의 부분$)$. $D_2$: $r\\le2\\sin\\theta$, 두 원은 $2\\sin\\theta=1$, 즉 $\\theta=\\tfrac\\pi6,\\tfrac{5\\pi}6$에서 만나요.",
