   "q": "포물기둥 $x^2=4y$와 곡면 $6z=xy$의 교선을 $C$라 하자.<br>(a) $x=t$로 두고 $C$를 매개화하라.&emsp;(b) 원점에서 점 $\\big(4,4,\\tfrac83\\big)$까지 $C$의 길이를 구하라.&emsp;(c) 점 $\\big(4,4,\\tfrac83\\big)$에서의 단위접선벡터를 구하라.",
