   "q": "$f(x,y)=\\dfrac{x^4y^4}{(x^2+y^4)^3}$에 대해<br>(a) 원점을 지나는 모든 직선을 따라 $(x,y)\\to(0,0)$일 때 $f\\to0$임을 보여라.&emsp;(b) 그럼에도 $\\displaystyle\\lim_{(x,y)\\to(0,0)}f(x,y)$가 존재하지 않음을 보여라.",
