    "$=\\dfrac58+\\dfrac{5\\sqrt3\\pi}{24}\\approx0.625+1.134\\approx1.76\\ \\mathrm{cm^2}$&emsp;($A=\\tfrac12\\cdot150\\cdot\\tfrac12=37.5$)",
