   "q": "미분가능한 함수 $z=f(x,y)$의 그래프의 점 $(3,2,f(3,2))$에서의 접평면이 $x+2y-z=4$이다. $g(u,v)=f(u+v,\\ uv)$라 할 때<br>(a) $f(3,2),\\ f_x(3,2),\\ f_y(3,2)$를 구하라.&emsp;(b) 곡면 $z=g(u,v)$의 점 $(1,2,g(1,2))$에서의 접평면을 구하라.&emsp;(c) $g(1.1,\\ 1.9)$의 근삿값을 구하라.",
