   "sec": "14.5",
   "type": "14-chain2",
   "src": "2024 중간 7번 배경 (곡선 위 2계 도함수)",
   "q": "$f$는 2계 편도함수가 연속이고 점 $(1,1)$에서 $f_x=2,\\ f_y=-1,\\ f_{xx}=1,\\ f_{xy}=2,\\ f_{yy}=-3$이다. $g(t)=f(t^2,\\ t^3)$일 때 $g'(1)$과 $g''(1)$을 구하라.",
   "hint": "$\\mathbf r(t)=\\langle t^2,t^3\\rangle$이면 $g'=f_x x'+f_y y'$, $g''=f_{xx}(x')^2+2f_{xy}x'y'+f_{yy}(y')^2+f_x x''+f_y y''$ — 마지막 두 항을 빠뜨리기 쉬워요.",
   "ans": "$g'(1)=1,\\ g''(1)=-1$",
