   "src": "교재 14.6 심화형 (두 곡면의 수직 · 교선의 접선)",
   "q": "타원면 $x^2+2y^2+3z^2=6$과 곡면 $z=xy$에 대해<br>(a) 두 곡면이 점 $(1,1,1)$에서 수직으로 만남(법선끼리 수직)을 보여라.<br>(b) 두 곡면의 교선의 점 $(1,1,1)$에서의 접선의 매개방정식을 구하라.",
   "hint": "$F=x^2+2y^2+3z^2$, $G=xy-z$로 두면 법선은 $\\nabla F$, $\\nabla G$. 교선의 접선은 두 법선에 모두 수직 → $\\nabla F\\times\\nabla G$ 방향.",
   "ans": "(a) $\\nabla F\\cdot\\nabla G=0$&emsp;(b) $x=1+5t,\\ y=1-4t,\\ z=1+t$",
