   "src": "교재 14.6 심화형 (접평면이 만드는 사면체)",
   "q": "곡면 $xyz=1$ 위의 제1팔분공간의 점 $(a,b,c)$ ($a,b,c>0$)에서의 접평면과 세 좌표평면으로 둘러싸인 사면체의 부피가 점의 위치와 관계없이 일정함을 보이고, 그 값을 구하라.",
