   "q": "두 직선 $L_1:\\ x=2+s,\\ y=-1-s,\\ z=0$과 $L_2:\\ x=t,\\ y=1,\\ z=3-t$에 대해<br>(a) $L_1$ 위의 점 $P(s)$와 $L_2$ 위의 점 $Q(t)$ 사이 거리의 제곱 $D(s,t)$의 임계점을 구하고, 그것이 최솟값임을 보여 두 직선 사이의 거리를 구하라.<br>(b) 최단 거리를 이루는 두 점을 잇는 선분이 두 직선에 모두 수직임을 확인하라.",
   "hint": "$D(s,t)=(s-t+2)^2+(s+2)^2+(t-3)^2$. 연립방정식 $D_s=D_t=0$을 풀고 2계 판정법으로 확인. (12.5의 외적 공식과 비교해 보세요.)",
   "ans": "(a) $(s,t)=(-1,2)$에서 최솟값 $D=3$ → 거리 $\\sqrt3$&emsp;(b) 두 점 $(1,0,0)$, $(2,1,1)$, $\\langle1,1,1\\rangle$은 두 방향벡터와 수직",
