   "q": "두 곡면 $z=x^2+3y^2$과 $z=8-x^2-y^2$으로 둘러싸인 입체의 부피를 구하라.",
   "hint": "교선의 정사영: $x^2+3y^2=8-x^2-y^2 \\iff x^2+2y^2=4$ (타원). 높이 $8-2x^2-4y^2$를 타원 위에서 적분 — $y$로 먼저 적분하고 $\\int_{-2}^2(4-x^2)^{3/2}dx=6\\pi$를 쓰세요.",
