   "src": "2025 중간 4번 유형",
   "q": "$E$가 제1팔분공간에서 두 곡면 $z=(x^2+y^2)^2$과 $z=2xy$로 둘러싸인 입체일 때 $\\displaystyle\\iiint_E(x^2+y^2)\\,dV$를 계산하라.",
   "hint": "원주좌표: $(x^2+y^2)^2=r^4$, $2xy=r^2\\sin2\\theta$. 두 곡면 사이가 비어 있지 않으려면 $r^4\\le r^2\\sin2\\theta$, 즉 $r\\le\\sqrt{\\sin2\\theta}$.",
