   "src": "2022 중간 블럭2 9번 응용 (한 장 쌍곡면)",
   "q": "$E$가 한 장 쌍곡면 $x^2+y^2-z^2=1$의 안쪽(축을 포함하는 쪽)에서 두 평면 $z=-1$, $z=1$ 사이에 있는 입체일 때<br>(a) $E$의 부피&emsp;(b) $\\displaystyle\\iiint_E(x^2+y^2)\\,dV$를 구하라.",
   "hint": "$E=\\{-1\\le z\\le1,\\ 0\\le r\\le\\sqrt{1+z^2}\\}$ — 이번에는 $z$를 가장 바깥에 두고 높이 $z$마다 원판 단면을 적분하는 순서 ($dr\\,d\\theta\\,dz$)가 편해요.",
