   "q": "포물면 $z=x^2+y^2$과 평면 $z=2y$로 둘러싸인 밀도가 일정한 입체의 부피와 질량중심을 구하라.",
   "hint": "교선의 정사영: $x^2+y^2=2y \\iff r=2\\sin\\theta$ ($0\\le\\theta\\le\\pi$). 높이는 $2r\\sin\\theta-r^2$. $\\int_0^\\pi\\sin^4\\theta\\,d\\theta=\\tfrac{3\\pi}8$, $\\int_0^\\pi\\sin^6\\theta\\,d\\theta=\\tfrac{5\\pi}{16}$.",
