    "$\\displaystyle\\iiint y\\,dV=\\int_0^\\pi\\!\\!\\int_0^{2\\sin\\theta}(2r\\sin\\theta-r^2)r^2\\sin\\theta\\,dr\\,d\\theta=\\int_0^\\pi\\frac85\\sin^6\\theta\\,d\\theta=\\frac\\pi2$ → $\\bar y=1$",
    "$\\displaystyle\\iiint z\\,dV=\\int_0^\\pi\\!\\!\\int_0^{2\\sin\\theta}\\frac{4r^2\\sin^2\\theta-r^4}{2}\\,r\\,dr\\,d\\theta=\\int_0^\\pi\\frac{8}{3}\\sin^6\\theta\\,d\\theta=\\frac{5\\pi}{6}$ → $\\bar z=\\dfrac53$",
    "$yz$평면 대칭 → $\\bar x=0$"
