   "type": "15-cyl",
   "src": "교재 15.7 심화형 (직교좌표 → 원주좌표)",
   "q": "원주좌표로 바꾸어 계산하라. $$\\int_0^2\\!\\!\\int_0^{\\sqrt{2x-x^2}}\\!\\!\\int_0^{\\sqrt{x^2+y^2}}xz\\,dz\\,dy\\,dx$$",
   "hint": "$y=\\sqrt{2x-x^2} \\iff (x-1)^2+y^2=1,\\ y\\ge0$ → 극좌표 $0\\le r\\le2\\cos\\theta,\\ 0\\le\\theta\\le\\tfrac\\pi2$. $z$의 범위는 $0\\le z\\le r$.",
