   "q": "$\\mathbf F(x,y,z)=\\big\\langle y^2+axz,\\ bxy+z^2,\\ 3x^2+cyz\\big\\rangle$가 보존장이 되도록 상수 $a,b,c$를 정하고, 그때 퍼텐셜 함수 $f$를 구하라. 또 $C:\\ \\mathbf r(t)=\\langle\\cos\\pi t,\\ t,\\ t^2\\rangle\\ (0\\le t\\le1)$를 따라 $\\displaystyle\\int_C\\mathbf F\\cdot d\\mathbf r$를 구하라.",
   "hint": "교차 편도함수 조건 $P_y=Q_x,\\ P_z=R_x,\\ Q_z=R_y$. 퍼텐셜은 $f=\\int P\\,dx$에서 시작해 $y,z$ 항을 맞춰요.",
