   "src": "교재 16.3 심화형 (보존장 + 나머지로 분리)",
   "q": "$C$가 원 $x^2+y^2=4$ 위를 $(2,0)$에서 $(0,2)$까지 반시계 방향으로 가는 호일 때 $\\displaystyle\\int_C(2xy+y)\\,dx+(x^2+2y)\\,dy$를 계산하라.",
   "hint": "$\\mathbf F=\\langle2xy,\\ x^2+2y\\rangle+\\langle y,\\ 0\\rangle$로 나누면 앞부분은 $\\nabla(x^2y+y^2)$ — 기본정리로, 뒷부분 $\\int_Cy\\,dx$만 직접 계산해요.",
