   "src": "2022 기말 블럭1 2번 유형 (거의 보존장)",
   "q": "$\\mathbf F(x,y,z)=\\big\\langle yz+2x,\\ xz,\\ xy+y\\big\\rangle$이고 $C:\\ \\mathbf r(t)=\\langle\\cos t,\\ \\sin t,\\ \\cos t+\\sin3t\\rangle\\ (0\\le t\\le2\\pi)$일 때 $\\displaystyle\\oint_C\\mathbf F\\cdot d\\mathbf r$를 구하라.",
