   "type": "16-green",
   "src": "2022 기말 블럭2 4번 유형 (열린 곡선을 닫아서)",
   "q": "$\\mathbf F(x,y)=\\big\\langle y^2+xe^{x},\\ 2xy+2x+\\cos y\\big\\rangle$이고 $C$가 극곡선 $r=1+\\cos\\theta\\ (0\\le\\theta\\le\\pi)$를 $\\theta$가 커지는 방향으로 따라가는 곡선일 때, 그린 정리를 이용해 $\\displaystyle\\int_C\\mathbf F\\cdot d\\mathbf r$를 구하라.",
   "hint": "$C$는 $(2,0)$에서 $(0,0)$까지 가는 열린 곡선 → $x$축 선분 $L$: $(0,0)\\to(2,0)$을 붙이면 위쪽 반 심장형 영역의 양의 방향 경계. $Q_x-P_y=2$.",
