   "q": "(a) 그린 정리를 이용해, 양의 방향 경계 $C$를 갖는 영역 $D$의 무게중심이 $\\bar x=\\dfrac{1}{2A}\\displaystyle\\oint_Cx^2\\,dy,\\ \\ \\bar y=-\\dfrac{1}{2A}\\oint_Cy^2\\,dx$임을 보여라. ($A$는 $D$의 넓이)<br>(b) 사이클로이드 $x=t-\\sin t,\\ y=1-\\cos t\\ (0\\le t\\le2\\pi)$의 한 아치와 $x$축으로 둘러싸인 영역의 무게중심을 구하라.",
   "hint": "(a) $\\oint x^2dy$에서 $P=0,\\ Q=x^2$ → $\\iint2x\\,dA$. (b) 양의 방향 = $x$축을 왼→오, 아치는 $t$: $2\\pi\\to0$. $x$축 위에서는 $y=0$, $dy=0$이라 기여 $0$.",
