   "hint": "(b) $x=2\\cos t,\\ y=\\sin t$이면 분모가 상수 $4$. (c) 원 위에서 직접 하면 어렵지만, 원과 타원 사이 영역(원점 제외)에서 그린 정리를 쓰면 $\\oint_{\\text{원}}=\\oint_{\\text{타원}}$.",
